     "ex": "import sqlite3\ndb = sqlite3.connect(\":memory:\")\ndb.executescript(\"\"\"\nCREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), day TEXT, total REAL, status TEXT);\nINSERT INTO customers VALUES (1,'Sara','Cairo'),(2,'Omar','Giza'),(3,'Mona','Cairo'),(4,'Hany','Alexandria');\nINSERT INTO orders VALUES (1,1,'2026-09-02',1200,'paid'),(2,2,'2026-09-05',450.5,'paid'),(3,1,'2026-09-18',3100,'paid'),(4,3,'2026-09-20',90,'new'),(5,2,'2026-10-01',980,'cancelled');\n\"\"\")\nsql = \"\"\"\nWITH paid AS (\n    SELECT customer_id, total, strftime('%Y-%m', day) AS month FROM orders WHERE status = 'paid'\n), per_customer AS (\n    SELECT customer_id, month, SUM(total) AS spent FROM paid GROUP BY customer_id, month\n)\nSELECT c.name, p.month, p.spent FROM per_customer p JOIN customers c ON c.id = p.customer_id ORDER BY p.spent DESC\n\"\"\"\nfor row in db.execute(sql):\n    print(row)\nprint(db.execute(\"SELECT date('2026-10-01', '-30 days'), strftime('%W', '2026-10-01')\").fetchone())",
